create or replace function public.get_saved_feed() returns table(id uuid,professional_id uuid,professional_name text,avatar_url text,image_url text,caption text,category text,location text,price_from numeric,rating numeric,rating_count integer,is_verified boolean,like_count bigint,comment_count bigint,is_liked boolean,is_saved boolean,aspect_ratio numeric,created_at timestamptz) language sql stable security invoker set search_path='' as $$
select fp.id,p.id,coalesce(p.display_name,p.business_name),p.profile_photo_url,fp.image_url,fp.caption,i.name,coalesce(p.location,p.business_address),fp.price_from,fp.rating,fp.rating_count,p.is_verified,(select count(*) from public.feed_post_likes l where l.post_id=fp.id),(select count(*) from public.feed_post_comments c where c.post_id=fp.id),exists(select 1 from public.feed_post_likes l where l.post_id=fp.id and l.user_id=(select auth.uid())),true,fp.aspect_ratio,fp.created_at from public.feed_post_saves saved join public.feed_posts fp on fp.id=saved.post_id join public.professional_profiles p on p.id=fp.professional_id join public.interests i on i.id=fp.interest_id where saved.user_id=(select auth.uid()) and fp.is_published order by saved.created_at desc;
$$;
revoke all on function public.get_saved_feed() from public;grant execute on function public.get_saved_feed() to authenticated;
